import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { load } from 'cheerio';

const ContentFetcher = ({ baseUrl, className, problemNumber, renderContent }) => {
  const [content, setContent] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchContent = async () => {
      setLoading(true);
      setError(null);

      try {
        const url = `${baseUrl}${problemNumber}`;
        const response = await axios.get(url, {
          headers: {
            'User-Agent': 'Mozilla/5.0 (X11; Ubuntu; Linux x86_64; rv:109.0) Gecko/20100101 Firefox/115.0'
          },
        });

        const $ = load(response.data);
        // Using class selector instead of ID
        const problemContent = $(`.${className}`).html();

        if (!problemContent) {
          throw new Error('Problem content not found on page');
        }

        setContent({
          url,
          content: problemContent
        });

      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    if (problemNumber) {
      fetchContent();
    }
  }, [baseUrl, className, problemNumber]);

  if (loading) return <div className="loading-indicator">Loading problem #{problemNumber}...</div>;
  if (error) return <div className="error-message">Error: {error}</div>;
  if (!content) return <div className="no-content">No problem content available</div>;

  return renderContent ? renderContent(content) : (
    <div dangerouslySetInnerHTML={{ __html: content.content }} />
  );
};

export default ContentFetcher;
